package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.graphics.Rect;
import android.os.*;
import android.view.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.time.*;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import org.junit.Test;
import static org.junit.Assert.*;

/** Isolated dated records and actual native gestures. No playback, sensors or alarm delivery. */
public final class NightDialReportFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice d=UiDevice.getInstance(i);
    private interface Journey {void run(Scene scene)throws Exception;}
    private final class Scene implements AutoCloseable {
        final String name="night-report-"+UUID.randomUUID(),database=name+".db";final List<Activity> owned=new CopyOnWriteArrayList<>();final SharedPreferences plan=c.getSharedPreferences(name,0);final Map<String,?> original=new HashMap<>(Prefs.of(c).getAll());final Records.Factory records=Records.factory;final SleepPlans.Factory plans=SleepPlans.factory;final TimeZone zone=TimeZone.getDefault();
        final Application app=(Application)c.getApplicationContext();final Application.ActivityLifecycleCallbacks life=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};
        Scene()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertNull(SleepSoundService.snapshot());assertTrue(plan.edit().putInt("goal",480).putInt("bedtime",1350).putInt("wakeTime",420).commit());Records.factory=ctx->new Store(ctx,database);SleepPlans.factory=ctx->plan;TimeZone.setDefault(TimeZone.getTimeZone("Asia/Riyadh"));Appearance.save(c,false,0,0,false,false);app.registerActivityLifecycleCallbacks(life);}
        Store store(){return new Store(c,database);}
        <T extends Activity>T activity(Class<T> type){return type.cast(owned.stream().filter(a->type.isInstance(a)&&!a.isDestroyed()&&!a.isFinishing()).reduce((a,b)->b).orElseThrow());}
        <T extends Activity>T launch(Class<T> type,Intent intent)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(type.getName(),null,false);try{c.startActivity(intent.putExtra("visualReview",true).putExtra("verificationLabel","Design review · isolated saved data").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity found=monitor.waitForActivityWithTimeout(5000);assertNotNull(type.getSimpleName(),found);return type.cast(found);}finally{i.removeMonitor(monitor);}}
        void recreate(Class<? extends Activity> type)throws Exception{Activity before=activity(type);Instrumentation.ActivityMonitor monitor=i.addMonitor(type.getName(),null,false);try{i.runOnMainSync(before::recreate);assertNotNull(monitor.waitForActivityWithTimeout(5000));}finally{i.removeMonitor(monitor);}d.waitForIdle();}
        public void close()throws Exception{d.pressHome();i.runOnMainSync(()->owned.forEach(a->{if(!a.isDestroyed())a.finish();}));i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+6000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(40);for(Activity a:owned){if(a instanceof RecordReportActivity r)r.awaitReaders(10000);else if(a instanceof RecordEditorActivity r)r.awaitReaders(10000);else if(a instanceof HistoryActivity r)r.awaitReaders(10000);else if(a instanceof RecordSignalsActivity r)r.awaitReaders(10000);}RecordSaves.drain(10000);app.unregisterActivityLifecycleCallbacks(life);Records.factory=records;SleepPlans.factory=plans;TimeZone.setDefault(zone);SharedPreferences.Editor restore=Prefs.of(c).edit();for(String key:List.of(Appearance.AUTO,Appearance.THEME,Appearance.SIZE,Appearance.MOTION,Appearance.CONTRAST)){Object value=original.get(key);if(value instanceof Boolean)restore.putBoolean(key,(Boolean)value);else if(value instanceof Integer)restore.putInt(key,(Integer)value);else restore.remove(key);}assertTrue(restore.commit());assertEquals("No unrelated preference writes",original,Prefs.of(c).getAll());assertTrue("All scene windows destroyed",owned.stream().allMatch(Activity::isDestroyed));c.deleteDatabase(database);c.deleteSharedPreferences(name);}
    }
    private void scene(Journey journey)throws Exception{try(Scene scene=new Scene()){try{journey.run(scene);}catch(Exception|AssertionError error){File dir=new File(c.getExternalFilesDir(null),"verification");dir.mkdirs();d.takeScreenshot(new File(dir,"night-dial-report-failure.png"));d.dumpWindowHierarchy(new File(dir,"night-dial-report-failure.xml"));throw error;}}}
    private UiObject2 text(String value){UiObject2 found=d.wait(Until.findObject(By.text(value)),5000);assertNotNull(value,found);return found;}
    private UiObject2 description(String value)throws Exception{UiObject2 found=d.wait(Until.findObject(By.desc(value)),1500);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(value));found=d.wait(Until.findObject(By.desc(value)),5000);}assertNotNull(value,found);return found;}
    private void clickText(String value)throws Exception{UiObject2 found=d.wait(Until.findObject(By.text(value)),1500);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(value));found=text(value);}found.click();d.waitForIdle();}
    private void readable(String value){Rect bounds=text(value).getVisibleBounds();assertTrue(value+" must have readable width",bounds.width()>80);assertTrue(value+" must fit the display",bounds.left>=0&&bounds.right<=d.getDisplayWidth());}
    private void capture(String name)throws Exception{NightDialCapture.frame(i,c,d,"report-"+name);}
    private <T extends View>T find(View view,Class<T> type){if(type.isInstance(view))return type.cast(view);if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){T found=find(group.getChildAt(n),type);if(found!=null)return found;}return null;}
    private long time(int day,int hour,int minute){return ZonedDateTime.of(2026,10,day,hour,minute,0,0,ZoneId.of("Asia/Riyadh")).toInstant().toEpochMilli();}
    private void tracked(Store store,long id,long end,int minutes,boolean signals){long start=end-minutes*60000L;store.getWritableDatabase().execSQL("INSERT INTO sessions(id,start,end,active_ms,note,source,origin,zone,sensor) VALUES(?,?,?,?,'Synthetic report fixture','tracked','local','Asia/Riyadh','unspecified')",new Object[]{id,start,end,minutes*60000L});if(signals){android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{for(int n=0;n<minutes;n++){if(n>=150&&n<165)continue;store.epoch(id,start+n*60000L,start+(n+1)*60000L,.02+(n%11)*.013,.1+(n%9)*.017,null,300);}db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    private String raw(Store store,long id){return store.rows("SELECT * FROM sessions WHERE id=?",""+id).toString()+store.rows("SELECT * FROM epochs WHERE session=? ORDER BY time",""+id)+store.rows("SELECT * FROM tracking_pauses WHERE session=?",""+id);}
    @Test public void latestReadOnlySignalsDraftGateAndReviewedRestoreKeepAnnotations()throws Exception{scene(scene->{
        long id=1000,end=time(30,6,30),start=end-462*60000L;String originals;
        try(Store store=scene.store()){tracked(store,id,end,462,true);RecordDraft manual=new RecordDraft(time(27,22,30),time(28,6,30));manual.note="Manual source fixture";Records.create(store,manual,ZoneId.of("Asia/Riyadh"),System.currentTimeMillis());RecordDraft imported=new RecordDraft(time(26,22,30),time(27,6,30));long importedId=Records.create(store,imported,ZoneId.of("Asia/Riyadh"),System.currentTimeMillis());store.getWritableDatabase().execSQL("UPDATE sessions SET origin='imported' WHERE id=?",new Object[]{importedId});originals=raw(store,id);}
        scene.launch(MainActivity.class,new Intent(c,MainActivity.class));description("Report").click();assertTrue(d.wait(Until.hasObject(By.descContains("7 h 42 min recorded")),5000));assertTrue(d.hasObject(By.text("18 min short")));assertTrue(description("Night").isSelected());capture("night");
        description("Explore recorded signals").click();text("Night details");description("Noise signal").click();RecordSignalsActivity signals=scene.activity(RecordSignalsActivity.class);RecordChart[] graph={null};Rect[] area={null};i.runOnMainSync(()->{graph[0]=find(signals.getWindow().getDecorView(),RecordChart.class);assertNotNull(graph[0]);Rect bounds=new Rect();assertTrue(graph[0].getGlobalVisibleRect(bounds));assertEquals(graph[0].getHeight(),bounds.height());area[0]=bounds;});assertTrue(d.swipe(area[0].left+50,area[0].centerY(),area[0].right-40,area[0].centerY(),30));long[] inspected={-1};i.runOnMainSync(()->{assertNotNull(graph[0].inspectedTime());inspected[0]=graph[0].inspectedTime();assertTrue(graph[0].getContentDescription().toString().contains("relative"));});UiObject2 light=d.findObject(By.desc("Light signal unavailable; no saved measurements"));assertNotNull(light);assertFalse(light.isEnabled());capture("signal-scrub");scene.recreate(RecordSignalsActivity.class);assertTrue(description("Noise signal").isSelected());i.runOnMainSync(()->{RecordChart restored=find(scene.activity(RecordSignalsActivity.class).getWindow().getDecorView(),RecordChart.class);assertNotNull(restored);assertEquals(inspected[0],restored.inspectedTime().longValue());});capture("signal-restored");d.pressBack();assertTrue(d.wait(Until.hasObject(By.descContains("7 h 42 min recorded")),5000));
        description("History").click();text("Sleep history");description("Filter source Imported").click();readable("8 h 0 min");readable("Imported");capture("history-imported");assertEquals(1,d.findObjects(By.descStartsWith("Open record ")).size());description("Clear history filters").click();description("Filter source Recorded").click();description("Open record "+id+", 2026-10-30, 7 h 42 min, Phone recording").click();assertTrue(d.wait(Until.hasObject(By.descContains("7 h 42 min recorded")),5000));try(Store store=scene.store()){assertEquals(originals,raw(store,id));assertEquals(0,store.rows("SELECT * FROM record_edits WHERE session=?",""+id).size());}
        description("Edit sleep").click();text("Edit sleep");description("Notes or dream").setText("This stays in a draft");description("Back").click();text("Discard changes?");capture("dirty-back");scene.recreate(RecordEditorActivity.class);text("Discard changes?");capture("dirty-restored");clickText("Keep editing");assertEquals("This stays in a draft",description("Notes or dream").getText());description("Back").click();text("Discard changes?");clickText("Discard changes");assertTrue(d.wait(Until.hasObject(By.descContains("7 h 42 min recorded")),5000));
        try(Store store=scene.store()){RecordEntry record=Records.get(store,id);RecordDraft edited=record.edit.copy();edited.start=start+10*60000L;edited.end=end-2*60000L;edited.awake.add(new RecordIntervals.Span(start+60*60000L,start+65*60000L));edited.note="Keep my notes";edited.addTag("Late meal");edited.rated=true;edited.rating=4;Records.save(store,id,edited,record.updated,System.currentTimeMillis());}
        scene.launch(RecordReportActivity.class,new Intent(c,RecordReportActivity.class).putExtra("record",id));assertTrue(d.wait(Until.hasObject(By.descContains("7 h 25 min recorded")),5000));description("Edit sleep").click();text("Edit sleep");description("Record options").click();clickText("Restore original record");text("Restore original times");capture("restore-review");scene.recreate(RecordEditorActivity.class);text("Restore original times");assertFalse(d.findObject(By.text("Also restore original notes, tags and rating")).isChecked());capture("restore-review-restored");clickText("Use original times");assertTrue(d.wait(Until.gone(By.text("Restore original times")),5000));assertEquals("Keep my notes",description("Notes or dream").getText());try(Store store=scene.store()){assertEquals(start+10*60000L,Records.get(store,id).edit.start);assertEquals(originals,raw(store,id));}capture("restore-draft");clickText("Save changes");assertTrue(d.wait(Until.hasObject(By.descContains("7 h 42 min recorded")),5000));try(Store store=scene.store()){RecordEntry saved=Records.get(store,id);assertEquals(start,saved.edit.start);assertEquals(end,saved.edit.end);assertTrue(saved.edit.awake.isEmpty());assertEquals("Keep my notes",saved.edit.note);assertEquals(List.of("Late meal"),saved.edit.tags);assertTrue(saved.edit.rated);assertEquals(4,saved.edit.rating);assertEquals(originals,raw(store,id));Backup.validate(store.backup());}capture("restored-night");assertFalse(TrackingService.running);assertNull(SleepSoundService.snapshot());
    });}
    @Test public void canonicalWeekUsesObservedDaysAndMissingRangesRemainUnknown()throws Exception{scene(scene->{
        int[] minutes={440,490,460,470,450,474,450};try(Store store=scene.store()){for(int n=0;n<minutes.length;n++)tracked(store,2000+n,time(23+n,7,0),minutes[n],false);}
        scene.launch(HistoryActivity.class,new Intent(c,HistoryActivity.class).putExtra("trends",true));text("Trends");text("7 h 42 min");readable("7 of 7 days");readable("8 h current goal");capture("trends-week");description("Month").click();readable("7 of 31 days");text("7 h 42 min");capture("trends-month");description("Year").click();readable("7 of 365 days");text("7 h 42 min");capture("trends-year");description("Week").click();description("Next week").click();readable("0 of 7 days");capture("trends-empty");assertFalse(description("Read details").isEnabled());new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text("No nights in this range"));text("No nights in this range");capture("trends-empty-actions");description("Previous week").click();text("7 of 7 days");scene.recreate(HistoryActivity.class);text("7 of 7 days");text("7 h 42 min");capture("trends-restored");assertFalse(TrackingService.running);assertNull(SleepSoundService.snapshot());
    });}
}
